/**
 * Explore destination — editorial collections for discovery.
 * Catalog sleeves lead. Channel pictograms are bugs when a lane has no cover.
 */

import {
  CHANNEL_ART,
  CHANNEL_ART_FOCUS,
  HERO_IDLE_ART,
  HERO_IDLE_FOCUS,
  isChannelPictogram,
} from "./channelArt";
import { genreStory, scenesForLane, tracksForGenreLane, tracksForScenePool } from "./browse";
import { CANONICAL_GENRES, normalizeGenre } from "./genres";
import {
  buildSceneChannelPool,
  decorateSceneChannels,
  SCENE_CHANNELS,
} from "./sceneChannels";
import { featuredReleases, recommendedPicks, trendingTracks } from "./homeCollections";
import { SCENE_FAMILIES, SCENES, getScene, trackMatchesScene } from "./scenes";

/** Canonical lane → Channel Surfing icon when the match is honest. */
export const GENRE_CHANNEL_ART = {
  Electronic: "techno",
  "Hip-Hop": "variety-mix",
  "R&B & Soul": "downtempo",
  Pop: "y2k-dance",
  Rock: "psychedelic-rock",
  Metal: "metal",
  "Country & Folk": "country-folk",
};

/** Scene family → Channel Surfing icon (same original set). */
export const FAMILY_CHANNEL_ART = {
  dancefloor: "house",
  bass: "drum-and-bass",
  afterhours: "downtempo",
  "soul-continuum": "downtempo",
  "jazz-world": "shoegaze",
  "rock-roots": "psychedelic-rock",
  "classical-score": "country-folk",
};

const PLAYABLE = (t) => (t?.duration || 0) <= 900;

function singles(tracks = []) {
  return tracks.filter(PLAYABLE);
}

export function coverUrlsForTracks(list = [], limit = 4) {
  const max = Math.max(1, limit);
  const seen = new Set();
  const out = [];
  for (const t of list) {
    const url = t?.albumCover;
    if (!url || seen.has(url) || isChannelPictogram(url)) continue;
    seen.add(url);
    out.push(url);
    if (out.length >= max) break;
  }
  return out;
}

export function artForChannelId(channelId) {
  if (!channelId) return { src: null, focus: "center" };
  return {
    src: CHANNEL_ART[channelId] || null,
    focus: CHANNEL_ART_FOCUS[channelId] || "center",
  };
}

function sleeveFirstVisual(channelPhoto, pool = []) {
  const covers = coverUrlsForTracks(pool, 4);
  const sleeve = covers[0] || null;
  return {
    photo: sleeve || null,
    photoFocus: sleeve ? "center" : channelPhoto.focus,
    covers,
    /** Single sleeve. False when a mosaic of covers should lead. Pictograms are bugs. */
    usePhoto: covers.length === 1 && !!sleeve,
    bug: channelPhoto.src,
  };
}

export function visualForGenre(lane, pool = []) {
  const channelId = GENRE_CHANNEL_ART[lane] || null;
  return sleeveFirstVisual(artForChannelId(channelId), pool);
}

export function visualForFamily(familyId, pool = []) {
  const channelId = FAMILY_CHANNEL_ART[familyId] || null;
  return sleeveFirstVisual(artForChannelId(channelId), pool);
}

/** Genre mosaic rows — only lanes that have catalog, plus art. */
export function exploreGenrePlates(tracks = []) {
  const playable = singles(tracks);
  const byLane = new Map();
  for (const t of playable) {
    const lane = normalizeGenre(t.genre);
    if (!lane) continue;
    const list = byLane.get(lane);
    if (list) list.push(t);
    else byLane.set(lane, [t]);
  }
  return CANONICAL_GENRES.filter((lane) => (byLane.get(lane) || []).length > 0).map((lane) => {
    const pool = byLane.get(lane) || [];
    const visual = visualForGenre(lane, pool);
    return {
      lane,
      story: genreStory(lane),
      sceneCount: scenesForLane(lane).length,
      trackCount: pool.length,
      scenes: scenesForLane(lane),
      ...visual,
    };
  });
}

/**
 * Mood / moment plates — energy rooms, not chip filters.
 * Photography is always a licensed channel still.
 */
export const MOOD_DEFS = [
  {
    id: "after-hours",
    label: "After hours",
    blurb: "Soft edges when the lights come up.",
    channelId: "downtempo",
    minEnergy: 0,
    maxEnergy: 4,
  },
  {
    id: "peak-time",
    label: "Peak time",
    blurb: "The floor at full pressure.",
    channelId: "techno",
    minEnergy: 7,
    maxEnergy: 10,
  },
  {
    id: "drive",
    label: "Drive",
    blurb: "Steady music for the road.",
    channelId: "local-pnw",
    minEnergy: 4,
    maxEnergy: 7,
  },
  {
    id: "late-booth",
    label: "Late booth",
    blurb: "Y2K dancefloor after midnight.",
    channelId: "y2k-dance",
    minEnergy: 5,
    maxEnergy: 9,
    genres: ["Electronic", "Pop"],
  },
];

export function tracksForMood(tracks = [], moodId) {
  const def = MOOD_DEFS.find((m) => m.id === moodId);
  if (!def) return [];
  let pool = singles(tracks).filter((t) => {
    const e = t.energy ?? 5;
    return e >= def.minEnergy && e <= def.maxEnergy;
  });
  if (def.genres?.length) {
    const focused = def.genres.flatMap((lane) => tracksForGenreLane(pool, lane));
    const seen = new Set();
    pool = focused.filter((t) => {
      if (seen.has(t.id)) return false;
      seen.add(t.id);
      return true;
    });
  }
  return pool.sort((a, b) => (b.playCount || 0) + (b.likeCount || 0) - ((a.playCount || 0) + (a.likeCount || 0)));
}

export function exploreMoodPlates(tracks = [], minTracks = 2) {
  return MOOD_DEFS.map((def) => {
    const pool = tracksForMood(tracks, def.id);
    const art = artForChannelId(def.channelId);
    const covers = coverUrlsForTracks(pool, 4);
    const sleeve = covers[0] || null;
    return {
      ...def,
      pool,
      count: pool.length,
      photo: sleeve || null,
      photoFocus: sleeve ? "center" : art.focus,
      covers,
      bug: art.src,
    };
  }).filter((m) => m.count >= minTracks);
}

/** Culture scenes with live counts — ranked by depth, photography from family. */
export function exploreScenePlates(tracks = [], limit = 10) {
  const playable = singles(tracks);
  const familyLabel = Object.fromEntries(SCENE_FAMILIES.map((f) => [f.id, f.label]));
  const scored = [];
  for (const scene of SCENES) {
    const pool = playable.filter((t) => trackMatchesScene(t, scene.id));
    if (!pool.length) continue;
    const art = artForChannelId(FAMILY_CHANNEL_ART[scene.familyId]);
    const covers = coverUrlsForTracks(pool, 4);
    const sleeve = covers[0] || null;
    scored.push({
      id: scene.id,
      label: scene.label,
      familyId: scene.familyId,
      familyLabel: familyLabel[scene.familyId] || scene.familyId,
      story: scene.story,
      cities: scene.cities || [],
      count: pool.length,
      pool,
      photo: sleeve || null,
      photoFocus: sleeve ? "center" : art.focus,
      covers,
      bug: art.src,
    });
  }
  return scored
    .sort((a, b) => b.count - a.count || a.label.localeCompare(b.label))
    .slice(0, limit);
}

export function recentlyPlayedTracks(tracks = [], recentTrackIds = [], limit = 12) {
  if (!recentTrackIds.length) return [];
  const byId = new Map(tracks.map((t) => [t.id, t]));
  const seen = new Set();
  const out = [];
  for (const id of recentTrackIds) {
    if (seen.has(id)) continue;
    seen.add(id);
    const t = byId.get(id);
    if (t) out.push(t);
    if (out.length >= limit) break;
  }
  return out;
}

export function exploreForYou(tracks = [], opts = {}) {
  const { preferredGenres = [], recentTrackIds = [], userKey = "", dayKey, limit = 16 } = opts;
  const { picks, coldStart } = recommendedPicks(tracks, {
    preferredGenres,
    recentTrackIds,
    limit,
    excludeIds: [],
    userKey,
    dayKey,
  });
  const trending = trendingTracks(tracks, limit);
  const seen = new Set();
  const rail = [];
  const reasons = {};
  const push = (list, asPicks = false) => {
    for (const item of list) {
      const t = asPicks ? item.track : item;
      if (!t?.id || seen.has(t.id)) continue;
      seen.add(t.id);
      rail.push(t);
      if (asPicks && item.reason) reasons[t.id] = item.reason;
      if (rail.length >= limit) return true;
    }
    return false;
  };
  if (push(picks, true)) return { tracks: rail, reasons, coldStart };
  if (push(trending)) return { tracks: rail, reasons, coldStart };
  push(recentlyPlayedTracks(tracks, recentTrackIds, 8));
  push(singles(tracks));
  return { tracks: rail, reasons, coldStart };
}

/**
 * Editorial hero — sleeves first.
 * Featured station when the dial is live (pool cover when catalog has art);
 * else a featured sleeve; else idle cassette drawing.
 * No “showcase station / N on the dial” chrome — title and tagline only.
 */
export function buildExploreHero({
  tracks = [],
  channels = [],
  releases = [],
  countdown = [],
} = {}) {
  const ready = (channels || []).filter((c) => c.ready !== false);
  const showcase = ready.find((c) => c.showcase) || ready[0] || null;

  if (showcase) {
    const channel = SCENE_CHANNELS.find((c) => c.id === showcase.id) || showcase;
    const pool = buildSceneChannelPool(tracks, channel);
    const covers = coverUrlsForTracks(pool, 4);
    const sleeve = covers[0] || null;
    const photoOverride =
      showcase.art && !isChannelPictogram(showcase.art) ? showcase.art : null;
    const art = sleeve || photoOverride;
    if (art) {
      return {
        kind: "channel",
        id: showcase.id,
        eyebrow: "",
        title: showcase.title,
        subtitle: showcase.tagline,
        kicker: null,
        art,
        artFocus: sleeve ? "center" : showcase.artFocus || "center",
        channel: showcase,
        album: null,
        track: pool[0] || null,
        pool,
      };
    }
  }

  const featured = (releases || [])[0];
  if (featured?.coverTrack?.albumCover) {
    return {
      kind: "release",
      id: featured.slug,
      eyebrow: "",
      title: featured.title,
      subtitle: featured.artist,
      kicker: featured.count ? `${featured.count} tracks` : null,
      art: featured.coverTrack.albumCover,
      artFocus: "center",
      channel: null,
      album: featured,
      track: featured.coverTrack,
      pool: featured.tracks || [],
    };
  }

  const chartTop = countdown?.[0]?.track;
  if (chartTop) {
    return {
      kind: "chart",
      id: chartTop.id,
      eyebrow: "On the board",
      title: chartTop.title,
      subtitle: chartTop.artist,
      kicker: "#1 this month",
      art: (chartTop.albumCover && !isChannelPictogram(chartTop.albumCover)
        ? chartTop.albumCover
        : HERO_IDLE_ART),
      artFocus: chartTop.albumCover && !isChannelPictogram(chartTop.albumCover)
        ? "center"
        : HERO_IDLE_FOCUS,
      channel: null,
      album: null,
      track: chartTop,
      pool: (countdown || []).map((c) => c.track).filter(Boolean),
    };
  }

  return {
    kind: "idle",
    id: "idle",
    eyebrow: "Explore",
    title: "Start anywhere",
    subtitle: "Stations, scenes, and sleeves — dig the catalog.",
    kicker: null,
    art: HERO_IDLE_ART,
    artFocus: HERO_IDLE_FOCUS,
    channel: null,
    album: null,
    track: null,
    pool: [],
  };
}

export function exploreStations(tracks = []) {
  return decorateSceneChannels(tracks);
}

export function exploreReleases(tracks = [], limit = 6) {
  return featuredReleases(tracks, limit);
}

export function exploreChartsTeaser(countdown = [], limit = 8) {
  return (countdown || []).slice(0, limit);
}

export function resolveExploreFocus(focus, tracks = []) {
  if (!focus?.type) return null;
  if (focus.type === "genre") {
    const pool = tracksForGenreLane(tracks, focus.id);
    const visual = visualForGenre(focus.id, pool);
    return {
      type: "genre",
      id: focus.id,
      label: focus.id,
      eyebrow: "Genre",
      story: genreStory(focus.id),
      pool,
      ...visual,
    };
  }
  if (focus.type === "scene") {
    const scene = getScene(focus.id);
    if (!scene) return null;
    const pool = tracksForScenePool(tracks, scene.id);
    const visual = visualForFamily(scene.familyId, pool);
    const family = SCENE_FAMILIES.find((f) => f.id === scene.familyId);
    return {
      type: "scene",
      id: scene.id,
      label: scene.label,
      eyebrow: family?.label || "Scene",
      story: scene.story,
      pool,
      cities: scene.cities || [],
      ...visual,
    };
  }
  if (focus.type === "mood") {
    const def = MOOD_DEFS.find((m) => m.id === focus.id);
    if (!def) return null;
    const pool = tracksForMood(tracks, def.id);
    const art = artForChannelId(def.channelId);
    const visual = sleeveFirstVisual(art, pool);
    return {
      type: "mood",
      id: def.id,
      label: def.label,
      eyebrow: "Mood",
      story: def.blurb,
      pool,
      ...visual,
    };
  }
  return null;
}
